const compiled={};
function escRe(value){return String(value).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function compile(lang){
  if(compiled[lang])return compiled[lang];
  const rows=[];
  for(const [source,target] of Object.entries(TEMPLATE_MAP[lang]||{})){
    const order=[];let cursor=0,pattern='^';
    source.replace(/\{\{MX(\d+)\}\}/g,(match,index,at)=>{pattern+=escRe(source.slice(cursor,at))+'(.+?)';order.push(Number(index));cursor=at+match.length;return match;});
    pattern+=escRe(source.slice(cursor))+'$';rows.push({re:new RegExp(pattern),target,order});
  }
  return compiled[lang]=rows;
}
function translate(value,lang){
  const text=String(value==null?'':value);if(lang!=='fr'&&lang!=='zh')return text;
  const exact=STRINGS[lang]&&STRINGS[lang][text];if(exact!==undefined)return exact;
  for(const row of compile(lang)){const match=text.match(row.re);if(!match)continue;const slots={};row.order.forEach((slot,index)=>{slots[slot]=match[index+1];});return row.target.replace(/\{\{MX(\d+)\}\}/g,(_m,index)=>slots[Number(index)]==null?'':slots[Number(index)]);}
  return text;
}
function applyLocaleFields(value,seen){
  if(!value||typeof value!=='object')return;seen=seen||new Set();if(seen.has(value))return;seen.add(value);
  if(typeof value.en==='string'){if(typeof value.fr!=='string')value.fr=translate(value.en,'fr');if(typeof value.zh!=='string')value.zh=translate(value.en,'zh');}
  Object.values(value).forEach(child=>applyLocaleFields(child,seen));
}
function preserveNonverbalStorySounds(universe){
  for(const episode of universe&&Array.isArray(universe.episodes)?universe.episodes:[]){
    for(const page of Array.isArray(episode.pages)?episode.pages:[]){
      if(page.speaker!=='moxy'&&page.speaker!=='cat')continue;
      const dialogue=page.dialogue;if(!dialogue||typeof dialogue.en!=='string')continue;
      dialogue.fr=dialogue.en;dialogue.zh=dialogue.en;
    }
  }
}
applyLocaleFields(root.MX_CAMPAIGN_LEVELS);applyLocaleFields(root.MX_STORY_UNIVERSE);preserveNonverbalStorySounds(root.MX_STORY_UNIVERSE);
root.MX_V2_LOCALIZATION={strings:STRINGS,templates:TEMPLATE_MAP,translate,applyLocaleFields};
